   */
  get name() {
    return this._name
  }

  /**
   * @method schema
   * @return {Object}
   */
  schema() {
    throw new Error('must override in subclass')
  }

  /**
   * @method configure
   * @param {MongooseSchema} schema
   */
  configure(schema) {
    schema.virtual('id').get(function () {
      return this._id
    })

    schema.set('toObject', {
      virtuals: true,
      getters: true
    })

    schema.set('toJSON', {
      virtuals: true,
      getters: true,
      transform: (ret, doc) => {
        this.toJSON(doc)
        return doc
      }
    })
  }

  /**
   * @method toJSON
   */
  toJSON(doc) {
    doc._id = doc.__t = doc.__v = undefined
  }

  /**
   * @method baseSchema
   * @return {Object}
   */
  baseSchema() {
    return {
      _id: {
        type: String,
        default: uuid,
        required: true
      },
      createdAt: {
        type: Date,
        default: Date.now,
        required: true,
        index: true
      },
      modifiedAt: {
        type: Date,
        default: Date.now,
        required: true
      },
      deleted: {
        type: Boolean,
        default: false,
        required: true
      }
    }
  }

  /**
   * @method schemaOptions
   * @return {Object}
   */
  schemaOptions() {
    return {
      autoIndex: process.env.NODE_ENV !== 'production'
    }
  }

  /**
   * @method createModel
   * @return {Class}
   */
  createModel() {
    const config = Object.assign({}, this.baseSchema(), this.schema())
    const options = this.schemaOptions()

    // Create and confugure the schema
    const schema = new mongodb.Schema(config, options)
    this.configure(schema)

    // Create the model
    const model = mongodb.createModel(this.name, schema)

    // Listen for index errors
    model.on('index', (err) => {
      if (err) throw err
    })

    return model
  }
}

